STAGE2_JS = r'''const DATA=JSON.parse(document.getElementById('adapter-data').textContent);const REC=DATA.recommendation;const C=REC.design_directions.candidates;let currentDirection=DATA.selected_direction||0;
function pickText(o,...keys){for(const k of keys){if(o&&typeof o[k]==='string'&&o[k].trim())return o[k]}return''}
function setSelect(id,value){const el=document.getElementById(id);if(!el)return;const vals=[...el.options].map(o=>o.value);el.value=vals.includes(String(value))?String(value):(vals.includes('custom')?'custom':vals[0]||'')}
function setColor(id,value){document.getElementById(id).value=/^#[0-9a-fA-F]{6}$/.test(value||'')?value:'#888888'}
function updateVisualStylePreview(){const host=document.getElementById('visual_style_preview');if(!host)return;const id=document.getElementById('visual_style').value;const uri=(DATA.style_preview_data||{})[id]||((DATA.direction_preview_data||[])[currentDirection]||'');const label=id==='custom'?'当前整套自定义方向的整页代理样本':'官方视觉风格 SVG 样本';host.innerHTML=uri?'<img src="'+uri+'" alt="visual style sample"><div class="style-sample-note">'+label+' · 样本用于判断整体视觉，不代表最终页面版式</div>':'<div class="style-sample-note">暂无可用样本</div>'}
function modeMiniSvg(id){const common='<svg viewBox="0 0 640 200" xmlns="http://www.w3.org/2000/svg"><rect width="640" height="200" fill="#fff"/>';const t='#172033',a='#5e6ad2',m='#dfe5ee';if(id==='pyramid')return common+'<rect x="170" y="24" width="300" height="42" rx="10" fill="'+a+'"/><rect x="45" y="112" width="160" height="54" rx="10" fill="'+m+'"/><rect x="240" y="112" width="160" height="54" rx="10" fill="'+m+'"/><rect x="435" y="112" width="160" height="54" rx="10" fill="'+m+'"/><path d="M320 66v25M125 91h390M125 91v21M320 91v21M515 91v21" stroke="'+t+'" stroke-width="4" fill="none"/></svg>';if(id==='narrative')return common+'<circle cx="110" cy="100" r="42" fill="#e8edff"/><circle cx="320" cy="100" r="42" fill="#fff1d6"/><circle cx="530" cy="100" r="42" fill="#e4f7ee"/><path d="M155 100h115M365 100h115" stroke="'+a+'" stroke-width="8" stroke-linecap="round"/><text x="110" y="106" text-anchor="middle" font-size="18" fill="'+t+'">情境</text><text x="320" y="106" text-anchor="middle" font-size="18" fill="'+t+'">张力</text><text x="530" y="106" text-anchor="middle" font-size="18" fill="'+t+'">解决</text></svg>';if(id==='instructional')return common+'<rect x="45" y="48" width="160" height="104" rx="14" fill="#eef2ff"/><rect x="240" y="48" width="160" height="104" rx="14" fill="#eef2ff"/><rect x="435" y="48" width="160" height="104" rx="14" fill="#eef2ff"/><text x="125" y="95" text-anchor="middle" font-size="32" font-weight="700" fill="'+a+'">1</text><text x="320" y="95" text-anchor="middle" font-size="32" font-weight="700" fill="'+a+'">2</text><text x="515" y="95" text-anchor="middle" font-size="32" font-weight="700" fill="'+a+'">3</text><text x="125" y="125" text-anchor="middle" font-size="15" fill="'+t+'">概念</text><text x="320" y="125" text-anchor="middle" font-size="15" fill="'+t+'">示范</text><text x="515" y="125" text-anchor="middle" font-size="15" fill="'+t+'">练习</text></svg>';if(id==='showcase')return common+'<rect x="32" y="26" width="576" height="148" rx="18" fill="#172033"/><text x="70" y="110" font-size="64" font-weight="800" fill="#fff">01</text><rect x="210" y="65" width="330" height="18" rx="9" fill="#fff"/><rect x="210" y="100" width="230" height="12" rx="6" fill="#718096"/></svg>';if(id==='briefing')return common+'<rect x="34" y="30" width="270" height="60" rx="10" fill="'+m+'"/><rect x="336" y="30" width="270" height="60" rx="10" fill="'+m+'"/><rect x="34" y="110" width="270" height="60" rx="10" fill="'+m+'"/><rect x="336" y="110" width="270" height="60" rx="10" fill="'+m+'"/></svg>';return common+'<rect x="48" y="42" width="544" height="116" rx="16" fill="#f5f7fb" stroke="#cfd7e3"/><text x="320" y="88" text-anchor="middle" font-size="20" font-weight="700" fill="'+t+'">项目专属 Custom Mode</text><text x="320" y="122" text-anchor="middle" font-size="14" fill="#718096">由下方 behavior 定义实际论证节奏</text></svg>'}
function updateModePreview(){const id=document.getElementById('mode').value,host=document.getElementById('mode_preview'),field=document.getElementById('mode_behavior_field');field.style.display=id==='custom'?'block':'none';let row=(DATA.mode_preview_catalog||[]).find(x=>x.id===id);let label=id==='custom'?'自定义表达模式':(row?row.label:id),desc=id==='custom'?(document.getElementById('mode_behavior').value.trim()||'当前整套方向使用项目专属表达骨架；它可能复用一个官方模式，也可能是多个模式的有目的组合。'):(row&&row.desc||'');host.innerHTML='<div class="semantic-preview-title">'+label+' · 结构示意</div><div class="semantic-preview-desc">'+desc+'</div><div class="mode-mini">'+modeMiniSvg(id)+'</div>'}
function iconPreviewMarkup(id){if(id==='emoji')return ['📊','💡','✅','🧭'].map((x,i)=>'<div class="icon-preview-cell"><div class="icon-preview-mark" style="font-size:30px">'+x+'</div><div class="icon-preview-name">Emoji</div></div>').join('');if(id==='none')return '<div class="semantic-preview-desc">不使用通用图标；页面仍可使用必要的品牌标识或内容自身符号。</div>';const rows=(DATA.icon_preview_data||{})[id]||[];return rows.map(x=>'<div class="icon-preview-cell"><div class="icon-preview-mark">'+x.svg+'</div><div class="icon-preview-name">'+x.name+'</div></div>').join('')||'<div class="semantic-preview-desc">暂无样本</div>'}
function updateIconPreview(){const id=document.getElementById('icons').value,host=document.getElementById('icon_preview'),cat=(DATA.catalogs.icons||[]).find(x=>x.id===id);const label=cat?(cat.label_zh||cat.label_en||cat.label||id):id,desc=cat?(cat.desc_zh||cat.desc_en||''):'';host.innerHTML='<div class="semantic-preview-title">'+label+' · 真实 SVG 样本</div><div class="semantic-preview-desc">'+desc+'</div><div class="icon-preview-grid">'+iconPreviewMarkup(id)+'</div>'}
function enforceImageUsage(changed){const all=[...document.querySelectorAll('input[name=image_usage]')];if(changed&&changed.checked&&changed.value==='none')all.forEach(x=>{if(x!==changed)x.checked=false});else if(changed&&changed.checked&&changed.value!=='none'){const none=all.find(x=>x.value==='none');if(none)none.checked=false}if(!all.some(x=>x.checked)){const none=all.find(x=>x.value==='none');if(none)none.checked=true}}
function updateImageStrategyReadout(){const u=imageUsage(),labels={ai:'生成配图',web:'网络来源',provided:'用户提供',placeholder:'占位符',none:'不使用图片'};const host=document.getElementById('image_usage_readout');host.innerHTML='<b>当前允许来源：</b>'+u.map(x=>labels[x]||x).join('、')+(u.includes('none')?'。后续不会规划图片资源。':'。这些只是允许的获取渠道，不代表每页都必须用图。');const notes=(document.getElementById('image_notes').value||'').trim(),warn=document.getElementById('image_notes_warning');const issues=[];if(/AI|生成图|生成配图|人工智能/i.test(notes)&&!u.includes('ai'))issues.push('说明提到生成图片，但当前未允许“生成配图”');if(/网络|web|网页|搜索/i.test(notes)&&!u.includes('web'))issues.push('说明提到网络图片，但当前未允许“网络来源”');if(/用户提供|提供的图片|已有图片/i.test(notes)&&!u.includes('provided'))issues.push('说明提到用户提供图片，但当前未允许“用户提供”');if(u.includes('none')&&notes&&!/不使用|不用|无图片|不需要图片/.test(notes))issues.push('当前选择“不使用图片”，但使用说明看起来仍在描述图片用途');if(issues.length){warn.style.display='block';warn.className='strategy-readout warning';warn.innerHTML='<b>请检查图片说明：</b>'+issues.join('；')+'。系统不会自动改写你的说明。'}else{warn.style.display='none';warn.textContent=''}}

function selectDirection(i){currentDirection=i;document.querySelectorAll('.direction').forEach((x,j)=>x.classList.toggle('active',j===i));const d=C[i];setSelect('mode',d.mode||'custom');document.getElementById('mode_behavior').value=pickText(d,'mode_behavior_zh','mode_behavior_en','mode_behavior');setSelect('visual_style',d.visual_style||'custom');document.getElementById('visual_style_behavior').value=pickText(d,'visual_style_behavior_zh','visual_style_behavior_en','visual_style_behavior');setSelect('icons',d.icons||'');const p=(d.color||{}).palette||{};['background','secondary_bg','primary','accent','secondary_accent','body_text'].forEach(r=>setColor('color_'+r,p[r]));const t=d.typography||{};setSelect('heading_font',((t.heading||{}).primary)||'');setSelect('heading_english',((t.heading||{}).english)||'');setSelect('body_font',((t.body||{}).primary)||'');setSelect('body_english',((t.body||{}).english)||'');document.getElementById('body_size').value=t.body_size||24;const sz=t.sizes||{};document.getElementById('size_title').value=sz.title||Math.round((t.body_size||24)*1.75);document.getElementById('size_subtitle').value=sz.subtitle||Math.round((t.body_size||24)*1.33);document.getElementById('size_annotation').value=sz.annotation||Math.round((t.body_size||24)*.75);const im=d.image_strategy||{};document.getElementById('image_rendering').value=im.rendering||'custom';document.getElementById('image_behavior').value=pickText(im,'behavior_zh','behavior_en','behavior');updateVisualStylePreview();updateModePreview();updateIconPreview()}
function init(){const r=REC.recommend||{};setSelect('delivery_purpose',r.delivery_purpose||'balanced');setSelect('generation_mode',r.generation_mode||'continuous');setSelect('image_ai_path',r.image_ai_path||'auto');const u=Array.isArray(r.image_usage)?r.image_usage:[r.image_usage||'none'];document.querySelectorAll('input[name=image_usage]').forEach(x=>x.checked=u.includes(x.value));document.getElementById('speaker_notes').checked=!!((REC.proactive_speaker_notes||{}).value??true);document.getElementById('custom_animations').checked=!!((REC.proactive_custom_animations||{}).value??false);document.getElementById('narration').checked=!!((REC.proactive_narration_audio||{}).value??false);document.getElementById('refine_spec').checked=!!((REC.refine_spec||{}).value??false);selectDirection(DATA.selected_direction||0);syncAi();updateImageStrategyReadout()}
function imageUsage(){let u=[...document.querySelectorAll('input[name=image_usage]:checked')].map(x=>x.value);if(u.includes('none')&&u.length>1)u=u.filter(x=>x!=='none');return u.length?u:['none']}
function syncAi(){document.getElementById('ai-controls').style.display=imageUsage().includes('ai')?'block':'none';updateImageStrategyReadout()}document.querySelectorAll('input[name=image_usage]').forEach(x=>x.addEventListener('change',()=>{enforceImageUsage(x);syncAi()}));document.getElementById('image_notes').addEventListener('input',updateImageStrategyReadout);
function num(id){const n=Number(document.getElementById(id).value);return Number.isFinite(n)&&n>0?n:null}
function generateStage2(){const mode=document.getElementById('mode').value,vs=document.getElementById('visual_style').value,u=imageUsage();if(mode==='custom'&&!document.getElementById('mode_behavior').value.trim()){document.getElementById('status').textContent='custom mode 需要 behavior';return}if(vs==='custom'&&!document.getElementById('visual_style_behavior').value.trim()){document.getElementById('status').textContent='custom visual style 需要 behavior';return}const pal={};['background','secondary_bg','primary','accent','secondary_accent','body_text'].forEach(r=>pal[r]=document.getElementById('color_'+r).value.toUpperCase());const typography={name:'static-ui-selection',heading:{primary:document.getElementById('heading_font').value,english:document.getElementById('heading_english').value,css:'sans-serif'},body:{primary:document.getElementById('body_font').value,english:document.getElementById('body_english').value,css:'sans-serif'},body_size:num('body_size'),body_size_unit:'px',sizes:{title:num('size_title'),subtitle:num('size_subtitle'),annotation:num('size_annotation')}};const values={stage:'final',page_count:document.getElementById('page_count').value,delivery_purpose:document.getElementById('delivery_purpose').value,mode,visual_style:vs,color:{name:'static-ui-selection',palette:pal},icons:document.getElementById('icons').value,typography,image_usage:u,image_notes:document.getElementById('image_notes').value,proactive_speaker_notes:document.getElementById('speaker_notes').checked,proactive_custom_animations:document.getElementById('custom_animations').checked,proactive_narration_audio:document.getElementById('narration').checked,generation_mode:document.getElementById('generation_mode').value,refine_spec:document.getElementById('refine_spec').checked};if(mode==='custom')values.mode_behavior=document.getElementById('mode_behavior').value;if(vs==='custom')values.visual_style_behavior=document.getElementById('visual_style_behavior').value;if(document.getElementById('template_application'))values.template_application=document.getElementById('template_application').value;if(u.includes('ai')){values.image_ai_path=document.getElementById('image_ai_path').value;values.image_strategy={name:'static-ui-selection',rendering:document.getElementById('image_rendering').value,behavior:document.getElementById('image_behavior').value}}putOutput({schema:'ppt-master-chat-confirm/v1',surface:'stage2',status:'user-confirmed',recommendation_sha256:DATA.recommendation_sha256,values});document.getElementById('status').textContent='已生成，可复制回 ChatGPT'}
document.getElementById('visual_style').addEventListener('change',()=>{updateVisualStylePreview();document.getElementById('visual_style_behavior_field').style.display=document.getElementById('visual_style').value==='custom'?'block':'none'});document.getElementById('mode').addEventListener('change',updateModePreview);document.getElementById('mode_behavior').addEventListener('input',updateModePreview);document.getElementById('icons').addEventListener('change',updateIconPreview);init();document.getElementById('visual_style_behavior_field').style.display=document.getElementById('visual_style').value==='custom'?'block':'none';'''
